window.RP_SESSION={"id":"S-d909777eef5a","messages":[{"id":"RP-II-0099700","time":"2026-05-11T22:09:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 아.... \"\n\n 며칠 동안 룸메인 토르번이 보이질 않습니다. 꽤 긴 의뢰라도 갔는지, 요즘 코빼기도 안 보여요.\n\n\" 이 형님.. 어디 가셨을까.. \"","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0099701","time":"2026-05-11T22:10:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":" 심심함에 의자에 앉아, 몸을 뒤로 젖히고, 아슬아슬하게 중심을 잡아봅니다.","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0099702","time":"2026-05-11T22:10:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0099703","time":"2026-05-11T22:10:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'하일로 조바'의 민첩 판정 :\n[2] + [1] = [3]\n결과 : 비극, 이 또한 당신의 운명입니다.","characters":[]},{"id":"RP-II-0099704","time":"2026-05-11T22:11:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 아 심심.. \"\n\n'휘익- 쿵-!'\n\n 결국, 중심을 잃고 뒤로 고꾸라져 뒤통수를 땅에 박아버렸네요..\n\n\" 아아..! 아악.. 아오 씨.. \"","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0099705","time":"2026-05-11T22:17:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":" 얼얼한 뒤통수를 문지른 후, 바이올린을 챙겨 밖으로 나가 봅니다..\n\n 심심함이 아픔을 이겼나 보네요.\n\n...\n\n 길드 옆에 시냇가..\n\n 눈을 감고 물 흐르는 소리를 느껴봅니다.","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0099706","time":"2026-05-11T22:17:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"음.. 굿","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0099707","time":"2026-05-11T22:18:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"https://youtu.be/DR-wA6RvET4?si=QwH8RFh4e13k11ei","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0099708","time":"2026-05-11T22:45:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"\" 소리 좋다.. \"\n\n 시냇물 소리에 만족스러운 웃음을 짓고, 바이올린을 켭니다. 바이올린은 시냇물과 조화를 이루며 아름다운 선율을 내었죠.\n\n\" ♩ ♪ 𝅘𝅥𝅮 ♫ ~ \"","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0099710","time":"2026-05-11T23:29:00+09:00","room":"RP II","name":"하일로 조바","profile":"하일로 조바","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-f6ccefd2c259"]},{"id":"RP-II-0099711","time":"2026-05-11T23:29:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]},{"id":"RP-II-0099712","time":"2026-05-11T23:30:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"unresolved","type":"dialogue","body":"https://youtu.be/P_DgrvZmXM0?si=EXNnktahkP215Xhu","characters":[]},{"id":"RP-II-0099713","time":"2026-05-11T23:30:00+09:00","room":"RP II","name":"스나가와 아이다","profile":"스나가와 아이다","identity":"unresolved","type":"dialogue","body":"사진","characters":[]}]};
